    let k5 = u32::from_le_bytes([buf[36], buf[37], buf[38], buf[39]]);
    let k6 = u32::from_le_bytes([buf[40], buf[41], buf[42], buf[43]]);
    let k7 = u32::from_le_bytes([buf[44], buf[45], buf[46], buf[47]]);
    let mut rounds = 8;
    while rounds > 0 {
        let t1 = (s1 >> 15) | (s2 << 17);
        let t2 = (s2 >> 6) | (s3 << 26);
        let t3 = (s2 >> 21) | (s3 << 11);
        let t4 = (s2 >> 27) | (s3 << 5);
        s0 ^= t1 ^ (t2 & t3) ^ t4 ^ k0;
        let t1 = (s2 >> 15) | (s3 << 17);
        let t2 = (s3 >> 6) | (s0 << 26);
        let t3 = (s3 >> 21) | (s0 << 11);
        let t4 = (s3 >> 27) | (s0 << 5);
        s1 ^= t1 ^ (t2 & t3) ^ t4 ^ k1;
        let t1 = (s3 >> 15) | (s0 << 17);
        let t2 = (s0 >> 6) | (s1 << 26);
        let t3 = (s0 >> 21) | (s1 << 11);
        let t4 = (s0 >> 27) | (s1 << 5);
        s2 ^= t1 ^ (t2 & t3) ^ t4 ^ k2;
        let t1 = (s0 >> 15) | (s1 << 17);
        let t2 = (s1 >> 6) | (s2 << 26);
        let t3 = (s1 >> 21) | (s2 << 11);
        let t4 = (s1 >> 27) | (s2 << 5);
        s3 ^= t1 ^ (t2 & t3) ^ t4 ^ k3;
        rounds -= 1;
        if rounds == 0 {
            break;
        }
        let t1 = (s1 >> 15) | (s2 << 17);
        let t2 = (s2 >> 6) | (s3 << 26);
        let t3 = (s2 >> 21) | (s3 << 11);
        let t4 = (s2 >> 27) | (s3 << 5);
        s0 ^= t1 ^ (t2 & t3) ^ t4 ^ k4;
        let t1 = (s2 >> 15) | (s3 << 17);
        let t2 = (s3 >> 6) | (s0 << 26);
        let t3 = (s3 >> 21) | (s0 << 11);
        let t4 = (s3 >> 27) | (s0 << 5);
        s1 ^= t1 ^ (t2 & t3) ^ t4 ^ k5;
        let t1 = (s3 >> 15) | (s0 << 17);
        let t2 = (s0 >> 6) | (s1 << 26);
        let t3 = (s0 >> 21) | (s1 << 11);
        let t4 = (s0 >> 27) | (s1 << 5);
        s2 ^= t1 ^ (t2 & t3) ^ t4 ^ k6;
        let t1 = (s0 >> 15) | (s1 << 17);
        let t2 = (s1 >> 6) | (s2 << 26);
        let t3 = (s1 >> 21) | (s2 << 11);
        let t4 = (s1 >> 27) | (s2 << 5);
        s3 ^= t1 ^ (t2 & t3) ^ t4 ^ k7;
        rounds -= 1;
    }
    let mut out = [0u8; 16];
    out[..4].copy_from_slice(&s0.to_le_bytes());
    out[4..8].copy_from_slice(&s1.to_le_bytes());
    out[8..12].copy_from_slice(&s2.to_le_bytes());
    out[12..16].copy_from_slice(&s3.to_le_bytes());
    out.to_vec()
}

