    // but the spec formula (x << r) | (x >> (32 - r)) with signed r and 32-bit
    // integers requires careful handling of the shift amounts to match the
    // test vectors provided. The test vectors imply that the rotation amount
    // is effectively (r % 32 + 32) % 32.
    let shift = ((r_val % 32) + 32) % 32;
    let s = shift as u32;
    if s == 0 {
        x
    } else {
        (x << s) | (x >> (32 - s))
    }
}

