pub fn mix_xnasam(x: u64, c: u64) -> u64 {
    let mut x = x ^ c;
    x ^= (x >> 25) | (x << 39);
    x ^= (x >> 47) | (x << 17);
    x = x.wrapping_mul(0x9E6C63D0676A9A99);
    x ^= x >> 23;
    x ^= x >> 51;
    x
}

pub fn mix_lea64(z: u64) -> u64 {
    let mut z = z;
    z = (z ^ (z >> 32)).wrapping_mul(0xdaba0b6eb09322e3);
    z = (z ^ (z >> 32)).wrapping_mul(0xdaba0b6eb09322e3);
    z ^ (z >> 32)
}

pub fn mix_pelican64(x: u64) -> u64 {
    let mut x = x;
    x ^= x >> 31;
    x = x.wrapping_mul(0x7fb5d329728ea185);
    x ^= x >> 27;
    x = x.wrapping_mul(0x81dadef4bc2dd44d);
    x ^= x >> 33;
    x
}

pub fn hash_boost64(seed: u64, v: u64) -> u64 {
    let mut s = seed;
    let term = v.wrapping_add(0x9e3779b97f4a7c15u64)
        .wrapping_add(s.wrapping_shl(12))
        .wrapping_add(s.wrapping_shr(4));
    s ^= term;
    s
}

pub fn splitmix_step(x: u64, gamma: u64) -> u64 {
    let mut z = x.wrapping_add(gamma);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
    z ^ (z >> 31)
}

pub fn rotl_mul64(x: u64) -> u64 {
    let mut x = x;
    x = (x << 23) | (x >> 41);
    x = x.wrapping_mul(0xff51afd7ed558ccd);
    x ^ (x >> 29)
}

pub fn weyl_step(s: u32) -> u32 {
    s.wrapping_add(0x9E3779B9u32)
}

pub fn jsf32_mix(x: u32) -> u32 {
    let e = x.wrapping_sub((x << 27) | (x >> 5));
    let result = e ^ ((x << 17) | (x >> 15));
    result
}

pub fn gjrand_mix(x: u32) -> u32 {
    let mut x = x;
    x ^= x << 11;
    x ^= x >> 8;
    x.wrapping_add(0x9e3779b9u32)
}

pub fn xorshift32_mul(x: u32) -> u32 {
    let mut x = x;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    x.wrapping_mul(0x2545F491u32)
}

pub fn lcg_msvc(seed: u32) -> u16 {
    let res = (seed.wrapping_mul(214013).wrapping_add(2531011)) >> 16;
    (res & 0x7fff) as u16
}

pub fn lcg_borland(state: u32) -> u32 {
    state.wrapping_mul(22695477).wrapping_add(1)
}

pub fn lcg_minstd(s: u32) -> u32 {
    ((s as u64).wrapping_mul(16807u64) % 2147483647u64) as u32
}

pub fn wyrand_step(state: u64) -> u64 {
    let mut s = state.wrapping_add(0xa0761d6478bd642f_u64);
    let xor_val = s ^ 0xe7037ed1a0b428db_u64;
    let product = (s as u128).wrapping_mul(xor_val as u128);
    let t = (product >> 64) as u64;
    let u = product as u64;
    t ^ u
}

pub fn euler_totient(n: u32) -> u32 {
    if n == 0 {
        return 0;
    }
    let mut n_val = n;
    let mut result = n;
    let mut p = 2u32;
    while (p as u64) * (p as u64) <= (n_val as u64) {
        if n_val % p == 0 {
            while n_val % p == 0 {
                n_val /= p;
            }
            result -= result / p;
        }
        p = p.wrapping_add(1);
    }
    if n_val > 1 {
        result -= result / n_val;
    }
    result
}

pub fn sum_divisors(n: u32) -> u32 {
    let mut s = 0u32;
    let mut i = 1u32;
    while (i as u64) * (i as u64) <= (n as u64) {
        if n % i == 0 {
            s = s.wrapping_add(i);
            let other = n / i;
            if i != other {
                s = s.wrapping_add(other);
            }
        }
        i = i.wrapping_add(1);
    }
    s
}

pub fn mobius(mut n: u32) -> i8 {
    if n == 1 {
        return 1;
    }
    if n == 0 {
        return 1;
    }
    let mut primes = 0;
    let mut p: u32 = 2;
    while (p as u64) * (p as u64) <= (n as u64) {
        if n % p == 0 {
            n /= p;
            if n % p == 0 {
                return 0;
            }
            primes += 1;
        }
        p += 1;
    }
    if n > 1 {
        primes += 1;
    }
    if (primes & 1) != 0 {
        -1
    } else {
        1
    }
}

pub fn is_prime_det(n: u32) -> i32 {
    if n < 2 {
        return 0;
    }
    if n < 4 {
        return 1;
    }
    if (n & 1) == 0 {
        return 0;
    }
    let mut i: u32 = 3;
    while (i as u64).wrapping_mul(i as u64) <= n as u64 {
        if n % i == 0 {
            return 0;
        }
        i = i.wrapping_add(2);
    }
    1
}

pub fn nth_fib(n: u32) -> u32 {
    let mut a: u32 = 0;
    let mut b: u32 = 1;
    for _ in 0..n {
        let t = a.wrapping_add(b);
        a = b;
        b = t;
    }
    a
}

pub fn tribonacci(n: u32) -> u32 {
    let mut a = 0u32;
    let mut b = 0u32;
    let mut c = 1u32;
    for _ in 0..n {
        let t = a.wrapping_add(b).wrapping_add(c);
        a = b;
        b = c;
        c = t;
    }
    a
}

pub fn radical(mut n: u32) -> u32 {
    let mut r = 1u32;
    let mut p = 2u32;
    while (p as u64).wrapping_mul(p as u64) <= n as u64 {
        if n % p == 0 {
            r = r.wrapping_mul(p);
            while n % p == 0 {
                n /= p;
            }
        }
        p = p.wrapping_add(1);
    }
    if n > 1 {
        r = r.wrapping_mul(n);
    }
    r
}

pub fn largest_prime_factor(n: u32) -> u32 {
    let mut n_val = n;
    let mut last = 1u32;
    while (n_val & 1 == 0) && n_val != 0 {
        last = 2;
        n_val >>= 1;
    }
    let mut i = 3u32;
    while (i as u64) * (i as u64) <= (n_val as u64) {
        while n_val % i == 0 {
            last = i;
            n_val /= i;
        }
        i = i.wrapping_add(2);
    }
    if n_val > 1 {
        last = n_val;
    }
    last
}

pub fn submod32(a: u32, b: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let a_mod = a % m;
    let b_mod = b % m;
    if a_mod >= b_mod {
        a_mod - b_mod
    } else {
        a_mod.wrapping_add(m).wrapping_sub(b_mod)
    }
}

pub fn mulmod64(a: u64, b: u64, m: u64) -> u64 {
    if m == 0 {
        return 0;
    }
    let a_128 = a as u128;
    let b_128 = b as u128;
    let m_128 = m as u128;
    ((a_128 * b_128) % m_128) as u64
}

pub fn doublemod(a: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let a_reduced = a % m;
    (a_reduced.wrapping_add(a_reduced)) % m
}

pub fn divmod_floor(a: i32, b: i32) -> u32 {
    if b == 0 {
        return 0;
    }
    let mut q = a / b;
    if (a % b != 0) && ((a < 0) != (b < 0)) {
        q = q.wrapping_sub(1);
    }
    q as u32
}

pub fn sqrmod(a: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let a_reduced = (a % m) as u64;
    let squared = a_reduced * a_reduced;
    ((squared % m as u64) as u32)
}

pub fn kr_hash(data: &[u8]) -> u32 {
    let mut h: u32 = 0;
    for &byte in data {
        h = h.wrapping_mul(31).wrapping_add(byte as u32);
    }
    h
}

pub fn kr_hash131(data: &[u8]) -> u32 {
    let mut h: u32 = 0;
    for &byte in data {
        h = h.wrapping_mul(131).wrapping_add(byte as u32);
    }
    h
}

pub fn add_rotate_hash(data: &[u8]) -> u32 {
    let mut h: u32 = 0;
    for &byte in data {
        h = h.wrapping_add(byte as u32);
        h = (h << 7) | (h >> 25);
    }
    h
}

pub fn fnv0_64(data: &[u8]) -> u64 {
    let mut h: u64 = 0;
    let fnv_prime: u64 = 1099511628211;
    for &byte in data {
        h = h.wrapping_mul(fnv_prime);
        h ^= byte as u64;
    }
    h
}

pub fn sat_mul_u8(a: u8, b: u8) -> u8 {
    let p = (a as u16).wrapping_mul(b as u16);
    if p > 0xFF {
        0xFF
    } else {
        p as u8
    }
}

pub fn abs_diff_u32(a: u32, b: u32) -> u32 {
    if a > b {
        a.wrapping_sub(b)
    } else {
        b.wrapping_sub(a)
    }
}

pub fn wrap_inc(x: u32, r#mod: u32) -> u32 {
    if r#mod == 0 {
        return 0;
    }
    let x_inc = x.wrapping_add(1);
    if x_inc >= r#mod {
        0
    } else {
        x_inc
    }
}

pub fn clamp_add(x: u32, d: u32, hi: u32) -> u32 {
    let s = (x as u64).wrapping_add(d as u64);
    if s > (hi as u64) {
        hi
    } else {
        s as u32
    }
}

pub fn clamp_sym(x: i32, bound: i32) -> i32 {
    let mut b = bound;
    if b < 0 {
        b = b.wrapping_neg();
    }
    if x > b {
        return b;
    }
    if x < b.wrapping_neg() {
        return b.wrapping_neg();
    }
    x
}

pub fn alpha_blend(a: u8, b: u8, t: u8) -> u8 {
    let a_u16 = a as u16;
    let b_u16 = b as u16;
    let t_u16 = t as u16;
    let res = (a_u16.wrapping_mul(255u16.wrapping_sub(t_u16)).wrapping_add(b_u16.wrapping_mul(t_u16)).wrapping_add(127)) / 255;
    res as u8
}

pub fn sign_extend8(x: u8) -> i32 {
    x as i8 as i32
}

pub fn clamp_to_i8(x: i32) -> i8 {
    if x > 127 {
        127
    } else if x < -128 {
        -128
    } else {
        x as i8
    }
}

pub fn saturate_bits(x: u32, bits: u32) -> u32 {
    let b = bits as i32;
    let max = if b >= 32 {
        0xFFFFFFFFu32
    } else {
        (1u32.wrapping_shl((b as u32) & 31)).wrapping_sub(1)
    };
    if x > max {
        max
    } else {
        x
    }
}

pub fn q24_8_mul(a: i32, b: i32) -> i32 {
    let a_64 = a as i64;
    let b_64 = b as i64;
    let prod = a_64.wrapping_mul(b_64);
    ((prod >> 8) as i32)
}

pub fn q24_8_div(a: i32, b: i32) -> i32 {
    if b == 0 {
        return 0;
    }
    let a_64 = a as i64;
    let b_64 = b as i64;
    let numerator = a_64.wrapping_shl(8);
    ((numerator / b_64) as i32)
}

pub fn q24_8_from_int(x: i32) -> i32 {
    x.wrapping_shl(8)
}

pub fn q24_8_to_int(x: i32) -> i32 {
    x >> 8
}

/// Q24 8 Floor
/// Performs a floor operation on a Q24.8 fixed-point number by truncating the
/// fractional part.
pub fn q24_8_floor(x: i32) -> i32 {
    x & -256
}

pub fn q24_8_frac(x: i32) -> i32 {
    x & 0xFF
}

pub fn q24_8_round(x: i32) -> i32 {
    let offset_x = x.wrapping_add(0x80);
    let mask = 0xFFFFFF00u32 as i32;
    offset_x & mask
}

pub fn q_lerp16(a: i32, b: i32, t: i32) -> i32 {
    let diff = b.wrapping_sub(a);
    let product = (diff as i64).wrapping_mul(t as i64);
    let scaled_diff = (product >> 16) as i32;
    a.wrapping_add(scaled_diff)
}

pub fn q24_8_abs(x: i32) -> i32 {
    if x < 0 {
        x.wrapping_neg()
    } else {
        x
    }
}

pub fn digit_count_base(n: u32, base: u32) -> u32 {
    if base < 2 {
        return 0;
    }
    let mut c: u32 = 0;
    let mut n_val = n;
    if n_val == 0 {
        return 1;
    }
    while n_val != 0 {
        c += 1;
        n_val /= base;
    }
    c
}

pub fn digit_sum_base(n: u32, base: u32) -> u32 {
    if base < 2 {
        return 0;
    }
    let mut s: u32 = 0;
    let mut n_val = n;
    while n_val != 0 {
        s = s.wrapping_add(n_val % base);
        n_val /= base;
    }
    s
}

pub fn reverse_base(n: u32, base: u32) -> u32 {
    if base < 2 {
        return 0;
    }
    let mut r: u32 = 0;
    let mut n_val = n;
    while n_val != 0 {
        r = r.wrapping_mul(base).wrapping_add(n_val % base);
        n_val /= base;
    }
    r
}

pub fn is_num_palindrome(n: u32, base: u32) -> i32 {
    if base < 2 {
        return 0;
    }
    let mut r: u32 = 0;
    let mut current_n = n;
    let o = n;
    while current_n != 0 {
        r = r.wrapping_mul(base).wrapping_add(current_n % base);
        current_n /= base;
    }
    if r == o {
        1
    } else {
        0
    }
}

pub fn ipow_checked(base: u32, exp: u32) -> u32 {
    let mut r: u32 = 1;
    let mut b: u32 = base;
    let mut e: u32 = exp;
    while e != 0 {
        if (e & 1) != 0 {
            r = r.wrapping_mul(b);
        }
        b = b.wrapping_mul(b);
        e >>= 1;
    }
    r
}

pub fn ilog_base(x: u32, base: u32) -> u32 {
    if base < 2 || x == 0 {
        return 0;
    }
    let mut x = x;
    let mut l = 0;
    while x >= base {
        x /= base;
        l += 1;
    }
    l
}

pub fn triangular(n: u32) -> u32 {
    n.wrapping_mul(n.wrapping_add(1)).wrapping_div(2)
}

pub fn sum_squares(n: u32) -> u32 {
    n.wrapping_mul(n.wrapping_add(1).wrapping_mul(n.wrapping_mul(2).wrapping_add(1))).wrapping_div(6)
}

pub fn count_trailing_zeros_dec(n: u32) -> u32 {
    if n == 0 {
        return 0;
    }
    let mut n = n;
    let mut c = 0;
    while n % 10 == 0 {
        c += 1;
        n /= 10;
    }
    c
}

pub fn gcd3(a: u32, b: u32, c: u32) -> u32 {
    let mut a = a;
    let mut b = b;
    let mut c = c;

    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }

    while c != 0 {
        let t = a % c;
        a = c;
        c = t;
    }

    a
}

pub fn rgb565_red(color: u16) -> u8 {
    let red_5bit = (color >> 11) & 0x1F;
    ((red_5bit as u32 * 255) / 31) as u8
}

pub fn rgb565_green(color: u16) -> u8 {
    let green_6bit = (color >> 5) & 0x3F;
    ((green_6bit as u32 * 255) / 63) as u8
}

pub fn argb_pack(a: u8, r: u8, g: u8, b: u8) -> u32 {
    ((a as u32) << 24) | ((r as u32) << 16) | ((g as u32) << 8) | (b as u32)
}

pub fn luminance601(r: u8, g: u8, b: u8) -> u8 {
    let r_u32 = r as u32;
    let g_u32 = g as u32;
    let b_u32 = b as u32;
    let sum = r_u32.wrapping_mul(299).wrapping_add(g_u32.wrapping_mul(587)).wrapping_add(b_u32.wrapping_mul(114));
    (sum / 1000) as u8
}

pub fn luminance709(r: u8, g: u8, b: u8) -> u8 {
    let r_u32 = r as u32;
    let g_u32 = g as u32;
    let b_u32 = b as u32;
    let sum = r_u32.wrapping_mul(2126)
        .wrapping_add(g_u32.wrapping_mul(7152))
        .wrapping_add(b_u32.wrapping_mul(722));
    (sum / 10000) as u8
}

pub fn channel_multiply(a: u8, b: u8) -> u8 {
    let a_u32 = a as u32;
    let b_u32 = b as u32;
    ((a_u32.wrapping_mul(b_u32).wrapping_add(127)) / 255) as u8
}

pub fn channel_screen(a: u8, b: u8) -> u8 {
    let a_u32 = a as u32;
    let b_u32 = b as u32;
    let inv_a = 255u32.wrapping_sub(a_u32);
    let inv_b = 255u32.wrapping_sub(b_u32);
    let prod = inv_a.wrapping_mul(inv_b);
    let res = 255u32.wrapping_sub(prod / 255);
    res as u8
}

pub fn rgb_to_grayscale(rgb: u32) -> u32 {
    let r = ((rgb >> 16) & 0xFF) as u32;
    let g = ((rgb >> 8) & 0xFF) as u32;
    let b = (rgb & 0xFF) as u32;
    let y = ((r.wrapping_mul(77).wrapping_add(g.wrapping_mul(150)).wrapping_add(b.wrapping_mul(29))) >> 8) as u8;
    ((y as u32) << 16) | ((y as u32) << 8) | (y as u32)
}

/// Crc32 Step
/// Computes a single step of the CRC-32 checksum algorithm for a single byte of
/// data.
///
/// Standards: IEEE 802.3, variant:ieee_reflected
pub fn crc32_step(crc: u32, byte: u8) -> u32 {
    let mut crc = crc ^ (byte as u32);
    for _ in 0..8 {
        if crc & 1 != 0 {
            crc = (crc >> 1) ^ 0xEDB88320;
        } else {
            crc >>= 1;
        }
    }
    crc
}

pub fn crc32c_step(crc: u32, byte: u8) -> u32 {
    let mut crc = crc ^ (byte as u32);
    for _ in 0..8 {
        if crc & 1 != 0 {
            crc = (crc >> 1) ^ 0x82F63B78;
        } else {
            crc >>= 1;
        }
    }
    crc
}

pub fn crc8_step(crc: u8, byte: u8) -> u8 {
    let mut crc = crc ^ byte;
    for _ in 0..8 {
        if (crc & 0x80) != 0 {
            crc = (crc << 1) ^ 0x07;
        } else {
            crc <<= 1;
        }
    }
    crc
}

pub fn adler_step(adler: u32, byte: u8) -> u32 {
    let mut a = adler & 0xFFFF;
    let mut b = (adler >> 16) & 0xFFFF;
    const ADLER_BASE: u32 = 65521;

    a = (a.wrapping_add(byte as u32)) % ADLER_BASE;
    b = (b.wrapping_add(a)) % ADLER_BASE;

    (b << 16) | a
}

pub fn fletcher16_step(state: u16, byte: u8) -> u16 {
    let mut s1 = (state & 0xFF) as u16;
    let mut s2 = ((state >> 8) & 0xFF) as u16;

    s1 = (s1 + byte as u16) % 255;
    s2 = (s2 + s1) % 255;

    (s2 << 8) | s1
}

pub fn xor_step(acc: u32, byte: u8) -> u32 {
    acc ^ (byte as u32)
}

/// Mix Murmurish
/// A lightweight non-cryptographic mixing function that applies multiplication and
/// bitwise rotation to improve the distribution of bits in a 32-bit integer.
pub fn mix_murmurish(h: u32) -> u32 {
    let mut h = h.wrapping_mul(0xcc9e2d51);
    h = h.rotate_left(15);
    h = h.wrapping_mul(0x1b873593);
    h
}

pub fn mix_fasthash32(h: u32) -> u32 {
    let mut h = h ^ (h >> 23);
    h = (h as u64).wrapping_mul(0x2127599bf4325c37u64) as u32;
    // In C, h >> 47 on a uint32_t is defined as 0 because 47 >= 32.
    // Rust panics on shifts >= bit width in debug mode. 
    // We must implement the logic such that it results in 0 to match C behavior.
    let h_shifted = if 47 >= 32 { 0 } else { h >> 47 };
    h ^ h_shifted
}

/// Mix Belloch
/// A non-cryptographic integer hash mixer designed to improve the distribution of
/// bits in a 32-bit integer.
pub fn mix_belloch(x: u32) -> u32 {
    let mut x = x;
    x = ((x >> 16) ^ x).wrapping_mul(0x45d9f3b);
    x = ((x >> 16) ^ x).wrapping_mul(0x45d9f3b);
    x = (x >> 16) ^ x;
    x
}

pub fn mix_pcg_output(x: u32) -> u32 {
    let mut x = x;
    x ^= x >> 16;
    x = x.wrapping_mul(0x7feb352d);
    x ^= x >> 15;
    x
}

pub fn mix_wyhash32(x: u32) -> u32 {
    let r = (x as u64).wrapping_mul(0xa0761d65u64);
    (r ^ (r >> 32)) as u32
}

pub fn mix_iqint1(x: u32) -> u32 {
    let mut x = x;
    x = (x.wrapping_shl(13)) ^ x;
    x = x.wrapping_mul(x.wrapping_mul(x).wrapping_mul(15731).wrapping_add(789221)).wrapping_add(1376312589);
    x
}

pub fn mix_hashint(a: u32) -> u32 {
    let mut a = a;
    a = a.wrapping_add(0x479ab41d).wrapping_add(a << 8);
