pub fn fix16_div(a: i32, b: i32) -> i32 {
    const FIX16_MINIMUM: i32 = i32::MIN;
    const FIX16_OVERFLOW: i32 = i32::MIN;
    if b == 0 {
        return FIX16_MINIMUM;
    }
    let mut remainder: u32 = a.unsigned_abs();
    let mut divider: u32 = b.unsigned_abs();
    let mut quotient: u64 = 0;
    let mut bit_pos: i32 = 17;
    if divider & 0xFFF0_0000 != 0 {
        let shifted_div: u32 = (divider >> 17) + 1;
        quotient = (remainder / shifted_div) as u64;
        let tmp: u64 = (quotient * divider as u64) >> 17;
        remainder = remainder.wrapping_sub(tmp as u32);
    }
    while (divider & 0xF) == 0 && bit_pos >= 4 {
        divider >>= 4;
        bit_pos -= 4;
    }
    while remainder != 0 && bit_pos >= 0 {
        let mut shift: i32 = remainder.leading_zeros() as i32;
        if shift > bit_pos {
            shift = bit_pos;
        }
        remainder <<= shift;
        bit_pos -= shift;
        let div: u32 = remainder / divider;
        remainder %= divider;
        quotient += (div as u64) << bit_pos;
        if div & !(0xFFFF_FFFFu32 >> bit_pos) != 0 {
            return FIX16_OVERFLOW;
        }
        remainder <<= 1;
        bit_pos -= 1;
    }
    quotient += 1;
    let mut result: i32 = (quotient >> 1) as i32;
    if ((a ^ b) as u32) & 0x8000_0000 != 0 {
        if result == FIX16_MINIMUM {
            return FIX16_OVERFLOW;
        }
        result = -result;
    }
    result
}

