pub fn catalan_mod(n: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let mut c: u64 = (1 % m as u64);
    for i in 0..n {
        let i_u64 = i as u64;
        // c = c * (2 * (2 * i + 1))
        let term1 = 2u64.wrapping_mul(2u64.wrapping_mul(i_u64).wrapping_add(1u64));
        c = c.wrapping_mul(term1);

        // d = i + 2
        let d = (i as u64).wrapping_add(2u64);

        // c /= 1 (no-op)

        // c %= ((uint64_t)m * d)
        let mod_val = (m as u64).wrapping_mul(d);
        c %= mod_val;

        // c %= m
        c %= m as u64;
    }
    (c % m as u64) as u32
}

