    }
    let mut r: u64 = 1 % (m as u64);
    let mut i: u32 = 0;
    while i < k_val {
        let term = (n.wrapping_sub(i) % m) as u64;
        r = (r * term) % (m as u64);
        i = i.wrapping_add(1);
    }
    r as u32
}

pub fn chinese2(a1: u32, n1: u32, a2: u32, n2: u32) -> u32 {
    if n1 == 0 || n2 == 0 {
        return 0;
    }
    let mut x: u64 = a1 as u64;
    let n1_u64 = n1 as u64;
    let n2_u64 = n2 as u64;
    let a2_mod_n2 = (a2 as u64) % n2_u64;

    while x % n2_u64 != a2_mod_n2 {
        x = x.wrapping_add(n1_u64);
    }

    let modulus = n1_u64.wrapping_mul(n2_u64);
    (x % modulus) as u32
}

pub fn pow2mod(e: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let mut e = e;
    let m_u64 = m as u64;
    let mut r = 1 % m_u64;
    let mut b = 2 % m_u64;
    while e > 0 {
        if (e & 1) != 0 {
            r = (r * b) % m_u64;
        }
        b = (b * b) % m_u64;
        e >>= 1;
    }
    r as u32
}

pub fn geomsum_mod(r: u32, n: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let mut sum: u64 = 0;
    let mut term: u64 = (1 % m as u64) as u64;
    let m_u64 = m as u64;
    let r_u64 = r as u64;

    for _ in 0..n {
        sum = (sum.wrapping_add(term)) % m_u64;
        term = (term.wrapping_mul(r_u64)) % m_u64;
    }

    sum as u32
}

pub fn fibmod(n: u32, m: u32) -> u32 {
    if m == 0 {
        return 0;
    }
    let mut a: u64 = 0;
    let mut b: u64 = 1 % (m as u64);
    for _ in 0..n {
        let c = (a.wrapping_add(b)) % (m as u64);
        a = b;
        b = c;
    }
    a as u32
}

pub fn zigzag_enc32(n: i32) -> u32 {
    ((n << 1) ^ (n >> 31)) as u32
}

pub fn gray_enc(x: u32) -> u32 {
    x ^ (x >> 1)
}

pub fn gray_dec(mut g: u32) -> u32 {
    g ^= g >> 16;
    g ^= g >> 8;
    g ^= g >> 4;
    g ^= g >> 2;
    g ^= g >> 1;
    g
}

pub fn bcd_to_bin(mut bcd: u32) -> u32 {
    let mut v: u32 = 0;
    let mut mul: u32 = 1;
    while bcd != 0 {
        v = v.wrapping_add((bcd & 0xF).wrapping_mul(mul));
        mul = mul.wrapping_mul(10);
        bcd >>= 4;
    }
    v
}

pub fn hex_val(c: i32) -> i32 {
    if c >= '0' as i32 && c <= '9' as i32 {
        return c.wrapping_sub('0' as i32);
    }
    if c >= 'a' as i32 && c <= 'f' as i32 {
        return c.wrapping_sub('a' as i32).wrapping_add(10);
    }
    if c >= 'A' as i32 && c <= 'F' as i32 {
        return c.wrapping_sub('A' as i32).wrapping_add(10);
    }
    -1
}

pub fn is_leap_year(year: i32) -> i32 {
    if (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) {
        1
    } else {
        0
    }
}

pub fn days_in_month(year: i32, month: u8) -> i32 {
    if month < 1 || month > 12 {
        return 0;
    }
    let d: [i32; 12] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if month == 2 && ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
        return 29;
    }
    d[(month - 1) as usize]
}

pub fn hms_to_secs(h: i32, m: u32, s: u32) -> i32 {
    let h_secs = h.wrapping_mul(3600);
    let m_secs = (m as i32).wrapping_mul(60);
    let s_secs = s as i32;
    h_secs.wrapping_add(m_secs).wrapping_add(s_secs)
}

pub fn secs_to_min(secs: i32) -> i32 {
    (secs / 60) % 60
}

pub fn quarter_of_month(month: i32) -> i32 {
    (month.wrapping_sub(1) / 3).wrapping_add(1)
}

pub fn weekday_of_days(days: i32) -> i32 {
    let rem = days % 7;
    ((rem.wrapping_add(7).wrapping_add(4)) % 7) as i32
}

pub fn sum_u8(data: &[u8]) -> u32 {
    let mut s: u32 = 0;
    for i in 0..data.len() {
        s = s.wrapping_add(data[i] as u32);
    }
    s
}

pub fn max_u8(data: &[u8]) -> u8 {
    let n = data.len();
    if n == 0 {
        return 0;
    }
    let mut m = data[0];
    for i in 1..n {
        if data[i] > m {
            m = data[i];
        }
    }
    m
}

pub fn min_u8(data: &[u8]) -> u8 {
    let n = data.len();
    if n == 0 {
        return 0;
    }
    let mut m = data[0];
    for i in 1..n {
        if data[i] < m {
            m = data[i];
        }
    }
    m
}

pub fn argmax_u8(data: &[u8]) -> i32 {
    let n = data.len() as i32;
    if n <= 0 {
        return -1;
    }
    let mut mi: usize = 0;
    for i in 1..data.len() {
        if data[i] > data[mi] {
            mi = i;
        }
    }
    mi as i32
}

pub fn popcount_buf(data: &[u8]) -> u32 {
    let mut c: u32 = 0;
    for i in 0..data.len() {
        let mut x: u8 = data[i];
        while x != 0 {
            c = c.wrapping_add((x & 1) as u32);
            x >>= 1;
        }
    }
    c
}

pub fn dot_u8(d: &[u8]) -> u32 {
    let mut s: u32 = 0;
    let n = d.len();
    let mut i = 0usize;
    while i + 1 < n {
        let prod = (d[i] as u32).wrapping_mul(d[i + 1] as u32);
        s = s.wrapping_add(prod);
        i += 2;
    }
    s
}

pub fn max_run_equal(data: &[u8]) -> u32 {
    let n = data.len();
    if n == 0 {
        return 0;
    }
    let mut best: u32 = 1;
    let mut cur: u32 = 1;
    for i in 1..n {
        if data[i] == data[i - 1] {
            cur = cur.wrapping_add(1);
            if cur > best {
                best = cur;
            }
        } else {
            cur = 1;
        }
    }
    best
}

pub fn range_u8(data: &[u8]) -> u32 {
    let n = data.len();
    if n == 0 {
        return 0;
    }
    let mut mn = data[0];
    let mut mx = data[0];
    for i in 1..n {
        let val = data[i];
        if val < mn {
            mn = val;
        }
        if val > mx {
            mx = val;
        }
    }
    (mx as u32).wrapping_sub(mn as u32)
}

pub fn checksum_weighted(data: &[u8]) -> u32 {
    let mut s: u32 = 0;
    for i in 0..data.len() {
        let weight = (i as u32).wrapping_add(1);
        let val = data[i] as u32;
        s = s.wrapping_add(weight.wrapping_mul(val));
    }
    s
}

pub fn rs_hash(data: &[u8]) -> u32 {
    let mut a: u32 = 63689u32;
    let mut b: u32 = 378551u32;
    let mut h: u32 = 0u32;

    for &byte in data {
        h = h.wrapping_mul(a).wrapping_add(byte as u32);
        a = a.wrapping_mul(b);
    }

    h
}

pub fn crc16_xmodem(data: &[u8]) -> u16 {
    let mut c: u16 = 0;
    for &byte in data {
        c ^= (byte as u16) << 8;
        for _ in 0..8 {
            if (c & 0x8000) != 0 {
                c = (c << 1) ^ 0x1021;
            } else {
                c <<= 1;
            }
        }
    }
    c
}

pub fn nlz32(mut x: u32) -> i32 {
    if x == 0 {
        return 32;
    }
    let mut n = 0;
    if x <= 0x0000FFFFu32 {
        n += 16;
        x <<= 16;
    }
    if x <= 0x00FFFFFFu32 {
        n += 8;
        x <<= 8;
    }
    if x <= 0x0FFFFFFFu32 {
        n += 4;
        x <<= 4;
    }
    if x <= 0x3FFFFFFFu32 {
        n += 2;
        x <<= 2;
    }
    if x <= 0x7FFFFFFFu32 {
        n += 1;
    }
    n
}

pub fn ch_to_upper(c: i32) -> i32 {
    if c >= b'a' as i32 && c <= b'z' as i32 {
        c.wrapping_sub(32)
    } else {
        c
    }
}

pub fn ch_to_lower(c: i32) -> i32 {
    if c >= b'A' as i32 && c <= b'Z' as i32 {
        c.wrapping_add(32)
    } else {
        c
    }
}

pub fn ch_is_alpha(c: i32) -> i32 {
    if (c >= b'a' as i32 && c <= b'z' as i32) || (c >= b'A' as i32 && c <= b'Z' as i32) {
        1
    } else {
        0
    }
}

pub fn ch_is_space(c: i32) -> i32 {
    if c == b' ' as i32
        || c == b'\t' as i32
        || c == b'\n' as i32
        || c == b'\r' as i32
        || c == b'v' as i32
        || c == b'f' as i32
    {
        1
    } else {
        0
    }
}

pub fn ch_swap_case(c: i32) -> i32 {
    if c >= b'a' as i32 && c <= b'z' as i32 {
        c.wrapping_sub(32)
    } else if c >= b'A' as i32 && c <= b'Z' as i32 {
        c.wrapping_add(32)
    } else {
        c
    }
}

pub fn ch_hex_val(c: i32) -> i32 {
    if c >= b'0' as i32 && c <= b'9' as i32 {
        c.wrapping_sub(b'0' as i32)
    } else if c >= b'a' as i32 && c <= b'f' as i32 {
        c.wrapping_sub(b'a' as i32).wrapping_add(10)
    } else if c >= b'A' as i32 && c <= b'F' as i32 {
        c.wrapping_sub(b'A' as i32).wrapping_add(10)
    } else {
        -1
    }
}

pub fn ch_rot13(c: i32) -> i32 {
    if c >= b'a' as i32 && c <= b'z' as i32 {
        b'a' as i32 + (c.wrapping_sub(b'a' as i32).wrapping_add(13) % 26)
    } else if c >= b'A' as i32 && c <= b'Z' as i32 {
        b'A' as i32 + (c.wrapping_sub(b'A' as i32).wrapping_add(13) % 26)
    } else {
        c
    }
}

