    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

#[inline]
fn ror(value: u32, bits: u32) -> u32 {
    (value >> bits) | (value << (32 - bits))
}

/// static void TransformFunction(Sha256Context*, uint8_t const*) — compress 512 bits.
fn transform(context: &mut Sha256Context, block: &[u8; 64]) {
    let mut s = [0u32; 8];
    let mut w = [0u32; 64];

    for i in 0..8 {
        s[i] = context.state[i];
    }
    // LOAD32H: big-endian words
    for i in 0..16 {
        w[i] = ((block[4 * i] as u32) << 24)
            | ((block[4 * i + 1] as u32) << 16)
            | ((block[4 * i + 2] as u32) << 8)
            | (block[4 * i + 3] as u32);
    }
    for i in 16..64 {
        let gamma1 = ror(w[i - 2], 17) ^ ror(w[i - 2], 19) ^ (w[i - 2] >> 10);
        let gamma0 = ror(w[i - 15], 7) ^ ror(w[i - 15], 18) ^ (w[i - 15] >> 3);
        w[i] = gamma1
            .wrapping_add(w[i - 7])
            .wrapping_add(gamma0)
            .wrapping_add(w[i - 16]);
    }
    // Compress: Sha256Round with the rotating S[] register trick.
    for i in 0..64 {
        let sigma1 = ror(s[4], 6) ^ ror(s[4], 11) ^ ror(s[4], 25);
        let ch = s[6] ^ (s[4] & (s[5] ^ s[6]));
        let t0 = s[7]
            .wrapping_add(sigma1)
            .wrapping_add(ch)
            .wrapping_add(K[i])
            .wrapping_add(w[i]);
        let sigma0 = ror(s[0], 2) ^ ror(s[0], 13) ^ ror(s[0], 22);
        let maj = ((s[0] | s[1]) & s[2]) | (s[0] & s[1]);
        let t1 = sigma0.wrapping_add(maj);
        s[3] = s[3].wrapping_add(t0); // d += t0
        s[7] = t0.wrapping_add(t1); // h = t0 + t1
        let t = s[7];
        s[7] = s[6];
        s[6] = s[5];
        s[5] = s[4];
        s[4] = s[3];
        s[3] = s[2];
        s[2] = s[1];
        s[1] = s[0];
        s[0] = t;
    }
    for i in 0..8 {
        context.state[i] = context.state[i].wrapping_add(s[i]);
    }
}

pub fn Sha256Initialise(context: &mut Sha256Context) {
    context.curlen = 0;
    context.length = 0;
    context.state[0] = 0x6A09E667;
    context.state[1] = 0xBB67AE85;
    context.state[2] = 0x3C6EF372;
    context.state[3] = 0xA54FF53A;
    context.state[4] = 0x510E527F;
    context.state[5] = 0x9B05688C;
    context.state[6] = 0x1F83D9AB;
    context.state[7] = 0x5BE0CD19;
}

pub fn Sha256Update(context: &mut Sha256Context, data: &[u8]) {
    if context.curlen >= 64 {
        return;
    }
    let mut off = 0usize;
    let mut remaining = data.len();
    while remaining > 0 {
        if context.curlen == 0 && remaining >= 64 {
            let mut block = [0u8; 64];
            block.copy_from_slice(&data[off..off + 64]);
            transform(context, &block);
            context.length = context.length.wrapping_add(64 * 8);
            off += 64;
            remaining -= 64;
        } else {
            let c = context.curlen as usize;
            let n = core::cmp::min(remaining, 64 - c);
            context.buf[c..c + n].copy_from_slice(&data[off..off + n]);
            context.curlen += n as u32;
            off += n;
            remaining -= n;
            if context.curlen == 64 {
                let block = context.buf;
                transform(context, &block);
                context.length = context.length.wrapping_add(8 * 64);
                context.curlen = 0;
            }
        }
    }
}

pub fn Sha256Finalise(context: &mut Sha256Context, digest: &mut [u8; 32]) {
    if context.curlen >= 64 {
        return;
    }
    context.length = context.length.wrapping_add(context.curlen as u64 * 8);
    // Append the '1' bit: buf[curlen++] = 0x80
    let c = context.curlen as usize;
    context.buf[c] = 0x80;
    context.curlen += 1;

    if context.curlen > 56 {
        while context.curlen < 64 {
            let c = context.curlen as usize;
            context.buf[c] = 0;
            context.curlen += 1;
        }
        let block = context.buf;
        transform(context, &block);
        context.curlen = 0;
    }
    while context.curlen < 56 {
        let c = context.curlen as usize;
        context.buf[c] = 0;
        context.curlen += 1;
    }
    // STORE64H(length, buf+56) — big-endian.
    let len = context.length;
    context.buf[56] = ((len >> 56) & 255) as u8;
    context.buf[57] = ((len >> 48) & 255) as u8;
    context.buf[58] = ((len >> 40) & 255) as u8;
    context.buf[59] = ((len >> 32) & 255) as u8;
    context.buf[60] = ((len >> 24) & 255) as u8;
    context.buf[61] = ((len >> 16) & 255) as u8;
    context.buf[62] = ((len >> 8) & 255) as u8;
    context.buf[63] = (len & 255) as u8;
    let block = context.buf;
    transform(context, &block);
    // STORE32H each state word big-endian into the digest.
    for i in 0..8 {
        let x = context.state[i];
        digest[4 * i] = ((x >> 24) & 255) as u8;
        digest[4 * i + 1] = ((x >> 16) & 255) as u8;
        digest[4 * i + 2] = ((x >> 8) & 255) as u8;
        digest[4 * i + 3] = (x & 255) as u8;
    }
}

