//! WjCryptLib MD5 — byte-exact safe-Rust port (frontier-claude crack).
//! Faithful translation of WjCryptLib_Md5.c (Colin Plumb / Alexander Peslyak,
//! public domain). Gated by the ctx-digest differential oracle (init->update->final
//! vs compiled C, 16-byte digest) + RFC 1321 KATs.
#![allow(non_snake_case, non_upper_case_globals, unused_imports, dead_code, clippy::needless_range_loop, clippy::too_many_arguments)]

use crate::*;

#[derive(Clone)]
pub struct Md5Context {
    pub lo: u32,
    pub hi: u32,
    pub a: u32,
    pub b: u32,
    pub c: u32,
    pub d: u32,
    pub buffer: [u8; 64],
    pub block: [u32; 16],
}

impl Default for Md5Context {
    fn default() -> Self {
        Md5Context { lo: 0, hi: 0, a: 0, b: 0, c: 0, d: 0, buffer: [0u8; 64], block: [0u32; 16] }
    }
}

#[inline]
fn rotl(x: u32, s: u32) -> u32 {
    (x << s) | ((x & 0xffffffff) >> (32 - s))
}
// F, G, H, I — the basic MD5 functions (Colin Plumb optimised forms).
#[inline]
fn func_f(x: u32, y: u32, z: u32) -> u32 { z ^ (x & (y ^ z)) }
#[inline]
fn func_g(x: u32, y: u32, z: u32) -> u32 { y ^ (z & (x ^ y)) }
#[inline]
fn func_h(x: u32, y: u32, z: u32) -> u32 { x ^ y ^ z }
#[inline]
fn func_i(x: u32, y: u32, z: u32) -> u32 { y ^ (x | !z) }

// STEP( f, a, b, c, d, x, t, s ): a += f(b,c,d)+x+t; a = rotl(a,s); a += b;
macro_rules! step {
    ($f:ident, $a:expr, $b:expr, $c:expr, $d:expr, $x:expr, $t:expr, $s:expr) => {
        $a = $a.wrapping_add($f($b, $c, $d)).wrapping_add($x).wrapping_add($t);
        $a = rotl($a, $s);
        $a = $a.wrapping_add($b);
    };
}

/// TransformFunction — process one or more 64-byte blocks (does NOT touch bit counters).
fn md5_transform(ctx: &mut Md5Context, data: &[u8]) {
    let mut a = ctx.a;
    let mut b = ctx.b;
    let mut c = ctx.c;
    let mut d = ctx.d;

    let mut base = 0usize;
    while base + 64 <= data.len() {
        let saved_a = a;
        let saved_b = b;
        let saved_c = c;
        let saved_d = d;
        // SET(n): load the 16 little-endian words for this block into ctx.block.
        for n in 0..16 {
            let p = base + n * 4;
            ctx.block[n] = (data[p] as u32)
                | ((data[p + 1] as u32) << 8)
                | ((data[p + 2] as u32) << 16)
                | ((data[p + 3] as u32) << 24);
        }
        let m = &ctx.block;

        // Round 1
        step!(func_f, a, b, c, d, m[0], 0xd76aa478, 7);
        step!(func_f, d, a, b, c, m[1], 0xe8c7b756, 12);
        step!(func_f, c, d, a, b, m[2], 0x242070db, 17);
        step!(func_f, b, c, d, a, m[3], 0xc1bdceee, 22);
        step!(func_f, a, b, c, d, m[4], 0xf57c0faf, 7);
        step!(func_f, d, a, b, c, m[5], 0x4787c62a, 12);
        step!(func_f, c, d, a, b, m[6], 0xa8304613, 17);
        step!(func_f, b, c, d, a, m[7], 0xfd469501, 22);
        step!(func_f, a, b, c, d, m[8], 0x698098d8, 7);
        step!(func_f, d, a, b, c, m[9], 0x8b44f7af, 12);
        step!(func_f, c, d, a, b, m[10], 0xffff5bb1, 17);
        step!(func_f, b, c, d, a, m[11], 0x895cd7be, 22);
        step!(func_f, a, b, c, d, m[12], 0x6b901122, 7);
        step!(func_f, d, a, b, c, m[13], 0xfd987193, 12);
        step!(func_f, c, d, a, b, m[14], 0xa679438e, 17);
        step!(func_f, b, c, d, a, m[15], 0x49b40821, 22);
        // Round 2
        step!(func_g, a, b, c, d, m[1], 0xf61e2562, 5);
        step!(func_g, d, a, b, c, m[6], 0xc040b340, 9);
