}

pub fn Md5Initialise(context: &mut Md5Context) {
    context.a = 0x67452301;
    context.b = 0xefcdab89;
    context.c = 0x98badcfe;
    context.d = 0x10325476;
    context.lo = 0;
    context.hi = 0;
}

pub fn Md5Update(context: &mut Md5Context, data: &[u8]) {
    let mut size = data.len() as u32;
    let mut off = 0usize;

    let saved_lo = context.lo;
    context.lo = saved_lo.wrapping_add(size) & 0x1fffffff;
    if context.lo < saved_lo {
        context.hi = context.hi.wrapping_add(1);
    }
    context.hi = context.hi.wrapping_add(size >> 29);

    let used = (saved_lo & 0x3f) as usize;
    if used != 0 {
        let free = 64 - used;
        if (size as usize) < free {
            context.buffer[used..used + size as usize].copy_from_slice(&data[off..off + size as usize]);
            return;
        }
        context.buffer[used..64].copy_from_slice(&data[off..off + free]);
        off += free;
        size -= free as u32;
        let buf = context.buffer;
        md5_transform(context, &buf);
    }

    if size >= 64 {
        let n = (size & !0x3f) as usize;
        md5_transform(context, &data[off..off + n]);
        off += n;
        size &= 0x3f;
    }

    context.buffer[0..size as usize].copy_from_slice(&data[off..off + size as usize]);
}

pub fn Md5Finalise(context: &mut Md5Context, digest: &mut [u8; 16]) {
    let mut used = (context.lo & 0x3f) as usize;
    context.buffer[used] = 0x80;
    used += 1;
    let mut free = 64 - used;

    if free < 8 {
        for k in 0..free {
            context.buffer[used + k] = 0;
        }
        let buf = context.buffer;
        md5_transform(context, &buf);
        used = 0;
        free = 64;
    }
    for k in 0..(free - 8) {
        context.buffer[used + k] = 0;
    }

    context.lo <<= 3;
    context.buffer[56] = context.lo as u8;
    context.buffer[57] = (context.lo >> 8) as u8;
    context.buffer[58] = (context.lo >> 16) as u8;
    context.buffer[59] = (context.lo >> 24) as u8;
    context.buffer[60] = context.hi as u8;
    context.buffer[61] = (context.hi >> 8) as u8;
    context.buffer[62] = (context.hi >> 16) as u8;
    context.buffer[63] = (context.hi >> 24) as u8;

    let buf = context.buffer;
    md5_transform(context, &buf);

    let words = [context.a, context.b, context.c, context.d];
    for (j, &word) in words.iter().enumerate() {
        digest[4 * j] = word as u8;
        digest[4 * j + 1] = (word >> 8) as u8;
        digest[4 * j + 2] = (word >> 16) as u8;
        digest[4 * j + 3] = (word >> 24) as u8;
    }
}

