//! WjCryptLib SHA-1 — byte-exact safe-Rust port (frontier-claude crack).
//! Faithful translation of WjCryptLib_Sha1.c (Steve Reid et al., public domain).
//! The C's little-endian shortcut (memcpy + blk0 byte-swap) is provably identical
//! to a big-endian word load, so this uses the endian-neutral big-endian form.
//! Gated by the ctx-digest differential oracle (init->update->final vs compiled C,
//! 20-byte digest) + NIST KATs.
#![allow(non_snake_case, non_upper_case_globals, unused_imports, dead_code, clippy::needless_range_loop, clippy::many_single_char_names)]

use crate::*;

#[derive(Clone)]
pub struct Sha1Context {
    pub State: [u32; 5],
    pub Count: [u32; 2],
    pub Buffer: [u8; 64],
}

impl Default for Sha1Context {
    fn default() -> Self {
        Sha1Context { State: [0u32; 5], Count: [0u32; 2], Buffer: [0u8; 64] }
    }
}

#[inline]
fn rol(value: u32, bits: u32) -> u32 {
    (value << bits) | (value >> (32 - bits))
}

/// TransformFunction — hash a single 512-bit block into state[5].
fn transform(state: &mut [u32; 5], buffer: &[u8; 64]) {
    // Load 16 big-endian words (== the shortcut's memcpy+blk0 result on LE).
    let mut w = [0u32; 16];
    for i in 0..16 {
        w[i] = ((buffer[i * 4] as u32) << 24)
            | ((buffer[i * 4 + 1] as u32) << 16)
            | ((buffer[i * 4 + 2] as u32) << 8)
            | (buffer[i * 4 + 3] as u32);
    }

    let mut a = state[0];
    let mut b = state[1];
    let mut c = state[2];
    let mut d = state[3];
    let mut e = state[4];

    for i in 0..80 {
        // blk0(i) for i<16 is the loaded word; blk(i) for i>=16 expands + stores back.
        let w_i = if i < 16 {
            w[i & 15]
        } else {
            let v = w[(i + 13) & 15] ^ w[(i + 8) & 15] ^ w[(i + 2) & 15] ^ w[i & 15];
            let r = rol(v, 1);
            w[i & 15] = r;
            r
        };
        let (f, k) = if i < 20 {
            (d ^ (b & (c ^ d)), 0x5A827999u32) // R0/R1: ((w&(x^y))^y)
        } else if i < 40 {
            (b ^ c ^ d, 0x6ED9EBA1u32) // R2
        } else if i < 60 {
            (((b | c) & d) | (b & c), 0x8F1BBCDCu32) // R3
        } else {
            (b ^ c ^ d, 0xCA62C1D6u32) // R4
        };
        let temp = rol(a, 5)
            .wrapping_add(f)
            .wrapping_add(e)
            .wrapping_add(k)
            .wrapping_add(w_i);
        e = d;
        d = c;
        c = rol(b, 30);
        b = a;
        a = temp;
    }

    state[0] = state[0].wrapping_add(a);
    state[1] = state[1].wrapping_add(b);
    state[2] = state[2].wrapping_add(c);
    state[3] = state[3].wrapping_add(d);
    state[4] = state[4].wrapping_add(e);
}

pub fn Sha1Initialise(context: &mut Sha1Context) {
    context.State[0] = 0x67452301;
    context.State[1] = 0xEFCDAB89;
    context.State[2] = 0x98BADCFE;
    context.State[3] = 0x10325476;
    context.State[4] = 0xC3D2E1F0;
    context.Count[0] = 0;
    context.Count[1] = 0;
}

pub fn Sha1Update(context: &mut Sha1Context, data: &[u8]) {
    let size = data.len() as u32;
    let mut j = (context.Count[0] >> 3) & 63;
    let add = size << 3;
    context.Count[0] = context.Count[0].wrapping_add(add);
    if context.Count[0] < add {
        context.Count[1] = context.Count[1].wrapping_add(1);
    }
    context.Count[1] = context.Count[1].wrapping_add(size >> 29);

    let mut i: u32;
    if (j + size) > 63 {
        i = 64 - j;
        context.Buffer[j as usize..64].copy_from_slice(&data[0..i as usize]);
        let buf = context.Buffer;
        transform(&mut context.State, &buf);
        while i + 63 < size {
            let mut block = [0u8; 64];
            block.copy_from_slice(&data[i as usize..i as usize + 64]);
            transform(&mut context.State, &block);
            i += 64;
        }
        j = 0;
    } else {
        i = 0;
    }
    let jlen = (size - i) as usize;
    context.Buffer[j as usize..j as usize + jlen].copy_from_slice(&data[i as usize..size as usize]);
}

pub fn Sha1Finalise(context: &mut Sha1Context, digest: &mut [u8; 20]) {
    let mut finalcount = [0u8; 8];
    for i in 0..8 {
        let idx = if i >= 4 { 0 } else { 1 };
        finalcount[i] = ((context.Count[idx] >> ((3 - (i & 3)) * 8)) & 255) as u8;
    }
    Sha1Update(context, &[0x80u8]);
    while (context.Count[0] & 504) != 448 {
        Sha1Update(context, &[0x00u8]);
    }
    Sha1Update(context, &finalcount); // triggers the final transform
    for i in 0..20 {
        digest[i] = ((context.State[i >> 2] >> ((3 - (i & 3)) * 8)) & 255) as u8;
    }
}

