#[inline]
fn ror(value: u64, bits: u32) -> u64 {
    (value >> bits) | (value << (64 - bits))
}

/// TransformFunction — compress 1024 bits.
fn transform(context: &mut Sha512Context, block: &[u8; 128]) {
    let mut s = [0u64; 8];
    let mut w = [0u64; 80];

    for i in 0..8 {
        s[i] = context.state[i];
    }
    // LOAD64H: big-endian 64-bit words
    for i in 0..16 {
        let mut v = 0u64;
        for j in 0..8 {
            v = (v << 8) | (block[8 * i + j] as u64);
        }
        w[i] = v;
    }
    for i in 16..80 {
        let gamma1 = ror(w[i - 2], 19) ^ ror(w[i - 2], 61) ^ (w[i - 2] >> 6);
        let gamma0 = ror(w[i - 15], 1) ^ ror(w[i - 15], 8) ^ (w[i - 15] >> 7);
        w[i] = gamma1
            .wrapping_add(w[i - 7])
            .wrapping_add(gamma0)
            .wrapping_add(w[i - 16]);
    }
    for i in 0..80 {
        let sigma1 = ror(s[4], 14) ^ ror(s[4], 18) ^ ror(s[4], 41);
        let ch = s[6] ^ (s[4] & (s[5] ^ s[6]));
        let t0 = s[7]
            .wrapping_add(sigma1)
            .wrapping_add(ch)
            .wrapping_add(K[i])
            .wrapping_add(w[i]);
        let sigma0 = ror(s[0], 28) ^ ror(s[0], 34) ^ ror(s[0], 39);
        let maj = ((s[0] | s[1]) & s[2]) | (s[0] & s[1]);
        let t1 = sigma0.wrapping_add(maj);
        s[3] = s[3].wrapping_add(t0);
        s[7] = t0.wrapping_add(t1);
        let t = s[7];
        s[7] = s[6];
        s[6] = s[5];
        s[5] = s[4];
        s[4] = s[3];
        s[3] = s[2];
        s[2] = s[1];
        s[1] = s[0];
        s[0] = t;
    }
    for i in 0..8 {
        context.state[i] = context.state[i].wrapping_add(s[i]);
    }
}

pub fn Sha512Initialise(context: &mut Sha512Context) {
    context.curlen = 0;
    context.length = 0;
    context.state[0] = 0x6a09e667f3bcc908;
    context.state[1] = 0xbb67ae8584caa73b;
    context.state[2] = 0x3c6ef372fe94f82b;
    context.state[3] = 0xa54ff53a5f1d36f1;
    context.state[4] = 0x510e527fade682d1;
    context.state[5] = 0x9b05688c2b3e6c1f;
    context.state[6] = 0x1f83d9abfb41bd6b;
    context.state[7] = 0x5be0cd19137e2179;
}

pub fn Sha512Update(context: &mut Sha512Context, data: &[u8]) {
    if context.curlen >= 128 {
        return;
    }
    let mut off = 0usize;
    let mut remaining = data.len();
    while remaining > 0 {
        if context.curlen == 0 && remaining >= 128 {
            let mut block = [0u8; 128];
            block.copy_from_slice(&data[off..off + 128]);
            transform(context, &block);
            context.length = context.length.wrapping_add(128 * 8);
            off += 128;
            remaining -= 128;
        } else {
            let c = context.curlen as usize;
            let n = core::cmp::min(remaining, 128 - c);
            context.buf[c..c + n].copy_from_slice(&data[off..off + n]);
            context.curlen += n as u32;
            off += n;
            remaining -= n;
            if context.curlen == 128 {
                let block = context.buf;
                transform(context, &block);
                context.length = context.length.wrapping_add(8 * 128);
                context.curlen = 0;
            }
        }
    }
}

pub fn Sha512Finalise(context: &mut Sha512Context, digest: &mut [u8; 64]) {
    if context.curlen >= 128 {
        return;
    }
    context.length = context.length.wrapping_add(context.curlen as u64 * 8);
    let c = context.curlen as usize;
    context.buf[c] = 0x80;
    context.curlen += 1;

    if context.curlen > 112 {
        while context.curlen < 128 {
            let c = context.curlen as usize;
            context.buf[c] = 0;
            context.curlen += 1;
        }
        let block = context.buf;
        transform(context, &block);
        context.curlen = 0;
    }
    while context.curlen < 120 {
        let c = context.curlen as usize;
        context.buf[c] = 0;
        context.curlen += 1;
    }
    // STORE64H(length, buf+120) — big-endian 64-bit (low 64 bits of the 128-bit length).
    let len = context.length;
    for j in 0..8 {
        context.buf[120 + j] = ((len >> (56 - 8 * j)) & 255) as u8;
    }
    let block = context.buf;
    transform(context, &block);
    // STORE64H each state word big-endian into the 64-byte digest.
    for i in 0..8 {
        let x = context.state[i];
        for j in 0..8 {
            digest[8 * i + j] = ((x >> (56 - 8 * j)) & 255) as u8;
        }
    }
}

