//! WjCryptLib RC4 — byte-exact safe-Rust port (frontier-claude crack).
//! Faithful translation of WjCryptLib_Rc4.c (WaterJuice, public domain). The
//! differential oracle drives init(key) + Rc4Output(N keystream bytes) with DropN=0,
//! compared byte-exact vs compiled C over random keys/lengths + RFC 6229 KATs.
#![allow(non_snake_case, non_upper_case_globals, unused_imports, dead_code, clippy::needless_range_loop)]

use crate::*;

#[derive(Clone)]
pub struct Rc4context {
    pub i: u32,
    pub j: u32,
    pub S: [u8; 256],
}

impl Default for Rc4context {
    fn default() -> Self {
        Rc4context { i: 0, j: 0, S: [0u8; 256] }
    }
}

/// Rc4Initialise with DropN = 0. KeySize is the slice length (must be 1..=256).
pub fn Rc4Initialise(context: &mut Rc4context, key: &[u8]) {
    // Setup key schedule (KSA).
    for i in 0..256 {
        context.S[i] = i as u8;
    }
    let keysize = key.len();
    let mut j: u32 = 0;
    for i in 0..256 {
        j = (j + context.S[i] as u32 + key[i % keysize] as u32) % 256;
        context.S.swap(i, j as usize);
    }
    context.i = 0;
    context.j = 0;
    // DropN = 0: no bytes discarded.
}

/// Rc4Output — emit the requested number of RC4 keystream bytes (PRGA).
pub fn Rc4Output(context: &mut Rc4context, buffer: &mut [u8]) {
    for n in 0..buffer.len() {
        context.i = (context.i + 1) % 256;
        context.j = (context.j + context.S[context.i as usize] as u32) % 256;
        context.S.swap(context.i as usize, context.j as usize);
        let idx = (context.S[context.i as usize] as u32 + context.S[context.j as usize] as u32) % 256;
        buffer[n] = context.S[idx as usize];
    }
}

