/// F(x): t = s[0][x>>24]; t += s[1][(x>>16)&0xff]; t ^= s[2][(x>>8)&0xff]; t += s[3][x&0xff]
#[inline]
fn f(keystruct: &BlowfishKey, x: u32) -> u32 {
    let mut t = keystruct.s[0][(x >> 24) as usize];
    t = t.wrapping_add(keystruct.s[1][((x >> 16) & 0xff) as usize]);
    t ^= keystruct.s[2][((x >> 8) & 0xff) as usize];
    t = t.wrapping_add(keystruct.s[3][(x & 0xff) as usize]);
    t
}

pub fn blowfish_encrypt(in_: &[u8], out: &mut [u8], keystruct: &BlowfishKey) {
    let mut l = ((in_[0] as u32) << 24) | ((in_[1] as u32) << 16) | ((in_[2] as u32) << 8) | (in_[3] as u32);
    let mut r = ((in_[4] as u32) << 24) | ((in_[5] as u32) << 16) | ((in_[6] as u32) << 8) | (in_[7] as u32);

    // 15 iterations with swap.
    for pval in 0..15usize {
        l ^= keystruct.p[pval];
        let t = f(keystruct, l);
        r ^= t;
        core::mem::swap(&mut l, &mut r); // swap(r,l,t)
    }
    // Last iteration has no swap.
    l ^= keystruct.p[15];
    let t = f(keystruct, l);
    r ^= t;
    r ^= keystruct.p[16];
    l ^= keystruct.p[17];

    out[0] = (l >> 24) as u8;
    out[1] = (l >> 16) as u8;
    out[2] = (l >> 8) as u8;
    out[3] = l as u8;
    out[4] = (r >> 24) as u8;
    out[5] = (r >> 16) as u8;
    out[6] = (r >> 8) as u8;
    out[7] = r as u8;
}

pub fn blowfish_key_setup(user_key: &[u8], keystruct: &mut BlowfishKey, len: usize) {
    // Copy the constant init arrays.
    keystruct.p = P_PERM;
    keystruct.s = S_PERM;

    // Combine the key with the P box.
    let mut idx2 = 0usize;
    for idx in 0..18usize {
        keystruct.p[idx] ^= ((user_key[idx2 % len] as u32) << 24)
            | ((user_key[(idx2 + 1) % len] as u32) << 16)
            | ((user_key[(idx2 + 2) % len] as u32) << 8)
            | (user_key[(idx2 + 3) % len] as u32);
        idx2 += 4;
    }

    // Re-calculate the P box.
    let mut block = [0u8; 8];
    let mut idx = 0usize;
    while idx < 18 {
        let b = block;
        blowfish_encrypt(&b, &mut block, keystruct);
        keystruct.p[idx] = ((block[0] as u32) << 24) | ((block[1] as u32) << 16)
            | ((block[2] as u32) << 8) | (block[3] as u32);
        keystruct.p[idx + 1] = ((block[4] as u32) << 24) | ((block[5] as u32) << 16)
            | ((block[6] as u32) << 8) | (block[7] as u32);
        idx += 2;
    }

    // Recalculate the S-boxes.
    for i in 0..4usize {
        let mut j = 0usize;
        while j < 256 {
            let b = block;
            blowfish_encrypt(&b, &mut block, keystruct);
            keystruct.s[i][j] = ((block[0] as u32) << 24) | ((block[1] as u32) << 16)
                | ((block[2] as u32) << 8) | (block[3] as u32);
            keystruct.s[i][j + 1] = ((block[4] as u32) << 24) | ((block[5] as u32) << 16)
                | ((block[6] as u32) << 8) | (block[7] as u32);
            j += 2;
        }
    }
}

