const RCON: [u32; 15] = [
    0x01000000, 0x02000000, 0x04000000, 0x08000000, 0x10000000, 0x20000000,
    0x40000000, 0x80000000, 0x1b000000, 0x36000000, 0x6c000000, 0xd8000000,
    0xab000000, 0x4d000000, 0x9a000000,
];

#[inline]
fn sub_word(w: u32) -> u32 {
    ((SBOX[((w >> 24) & 0xff) as usize] as u32) << 24)
        | ((SBOX[((w >> 16) & 0xff) as usize] as u32) << 16)
        | ((SBOX[((w >> 8) & 0xff) as usize] as u32) << 8)
        | (SBOX[(w & 0xff) as usize] as u32)
}

#[inline]
fn rotword(w: u32) -> u32 {
    (w << 8) | (w >> 24)
}

pub fn aes_key_setup(key: &[u8], w: &mut [u32], keysize: i32) {
    let (nr, nk): (usize, usize) = match keysize {
        128 => (10, 4),
        192 => (12, 6),
        256 => (14, 8),
        _ => return,
    };
    let nb = 4usize;
    for i in 0..nk {
        w[i] = ((key[4 * i] as u32) << 24)
            | ((key[4 * i + 1] as u32) << 16)
            | ((key[4 * i + 2] as u32) << 8)
            | (key[4 * i + 3] as u32);
    }
    for i in nk..(nb * (nr + 1)) {
        let mut temp = w[i - 1];
        if i % nk == 0 {
            temp = sub_word(rotword(temp)) ^ RCON[(i - 1) / nk];
        } else if nk > 6 && i % nk == 4 {
            temp = sub_word(temp);
        }
        w[i] = w[i - nk] ^ temp;
    }
}

#[inline]
fn xtime(x: u8) -> u8 {
    if x & 0x80 != 0 { (x << 1) ^ 0x1b } else { x << 1 }
}

fn add_round_key(state: &mut [u8; 16], w: &[u32]) {
    for c in 0..4 {
        let k = w[c];
        state[c * 4] ^= (k >> 24) as u8;
        state[c * 4 + 1] ^= (k >> 16) as u8;
        state[c * 4 + 2] ^= (k >> 8) as u8;
        state[c * 4 + 3] ^= k as u8;
    }
}

fn sub_bytes(state: &mut [u8; 16]) {
    for i in 0..16 {
        state[i] = SBOX[state[i] as usize];
    }
}

fn shift_rows(state: &mut [u8; 16]) {
    let s = *state;
    for r in 1..4 {
        for c in 0..4 {
            state[c * 4 + r] = s[((c + r) % 4) * 4 + r];
        }
    }
}

fn mix_columns(state: &mut [u8; 16]) {
    for c in 0..4 {
        let a0 = state[c * 4];
        let a1 = state[c * 4 + 1];
        let a2 = state[c * 4 + 2];
        let a3 = state[c * 4 + 3];
        state[c * 4] = xtime(a0) ^ (xtime(a1) ^ a1) ^ a2 ^ a3;
        state[c * 4 + 1] = a0 ^ xtime(a1) ^ (xtime(a2) ^ a2) ^ a3;
        state[c * 4 + 2] = a0 ^ a1 ^ xtime(a2) ^ (xtime(a3) ^ a3);
        state[c * 4 + 3] = (xtime(a0) ^ a0) ^ a1 ^ a2 ^ xtime(a3);
    }
}

pub fn aes_encrypt(in_: &[u8], out: &mut [u8], w: &[u32], keysize: i32) {
    let nr: usize = match keysize {
        128 => 10,
        192 => 12,
        256 => 14,
        _ => return,
    };
    let mut state = [0u8; 16];
    state.copy_from_slice(&in_[0..16]);

    add_round_key(&mut state, &w[0..4]);
    for round in 1..nr {
        sub_bytes(&mut state);
        shift_rows(&mut state);
        mix_columns(&mut state);
        add_round_key(&mut state, &w[4 * round..4 * round + 4]);
    }
    sub_bytes(&mut state);
    shift_rows(&mut state);
    add_round_key(&mut state, &w[4 * nr..4 * nr + 4]);

    out[0..16].copy_from_slice(&state);
}
